Tool response:
Tool: create_patient_with_insurance
Description: Register a new patient with the provided personal details and assign them an insurance policy. The insurance policy must already exist in the system. Returns the created patient's ID and insurance assignment details.
Parameters:
    {
      "type": "object",
      "properties": {
        "first_name": {
          "type": "string",
          "title": "First Name"
        },
        "last_name": {
          "type": "string",
          "title": "Last Name"
        },
        "date_of_birth": {
          "type": "string",
          "title": "Date Of Birth"
        },
        "phone": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Phone"
        },
        "address_line1": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Address Line1"
        },
        "address_line2": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Address Line2"
        },
        "city": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "City"
        },
        "state": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "State"
        },
        "postal_code": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Postal Code"
        },
        "insurance_policy_name": {
          "type": "string",
          "title": "Insurance Policy Name"
        },
        "member_id": {
          "type": "string",
          "title": "Member Id"
        },
        "group_number": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Group Number"
        }
      },
      "required": [
        "first_name",
        "last_name",
        "date_of_birth",
        "insurance_policy_name",
        "member_id"
      ]
    }
